--- Template -> Lua source. `render` is pure; `write` adds validation, the
--- backup and the atomic replace.
local Path = require "plenary.path"
local backup = require "keymap-helper.template.backup"
local schema = require "keymap-helper.template.schema"

local M = {}

M.MARK = "-- AUTOGENERATED by keymap-helper"

--- Width of the box-comment headers, in columns. Matches the headers the
--- hand-written file had, so `group_by = "header"` keeps finding them.
M.BOX_WIDTH = 80

--- @param template_name string path shown in the header
--- @param target string generated file, for the backup name
--- @return string[]
function M.header_lines(template_name, target)
  return {
    M.MARK .. " from " .. template_name .. ".",
    "-- DO NOT EDIT THIS FILE: your changes are overwritten the next time it is generated.",
    "-- To change a keymap: run :KeymapHelper edit, or edit " .. template_name .. ".",
    "-- Then run :KeymapHelper generate. Every generate keeps a backup of the old file.",
    ("-- To undo: copy the newest %s_<YYYY_MM_DD_hh:mm:ss>.bak over this file."):format(backup.stem(target)),
  }
end

--- The three-line box comment for a category.
--- @param title string
--- @param subtitle string|nil
--- @return string
function M.box(title, subtitle)
  local inner = M.BOX_WIDTH - 5 -- "-- " plus the two corner characters
  local fill = inner - 2 -- one space either side of the title
  local pad = fill - vim.fn.strdisplaywidth(title)
  local lines = {
    "-- ┌" .. ("─"):rep(inner) .. "┐",
    "-- │ " .. title .. (" "):rep(math.max(pad, 0)) .. " │",
    "-- └" .. ("─"):rep(inner) .. "┘",
  }
  if subtitle and subtitle ~= "" then
    lines[#lines + 1] = "-- " .. subtitle
  end
  return table.concat(lines, "\n")
end

local function quote(s)
  local esc = {
    ["\\"] = "\\\\",
    ['"'] = '\\"',
    ["\n"] = "\\n",
    ["\r"] = "\\r",
    ["\t"] = "\\t",
  }
  return '"' .. s:gsub('[\\"\n\r\t]', esc):gsub("%c", function(c)
    return ("\\%03d"):format(c:byte())
  end) .. '"'
end
M.quote = quote

local function opts_text(e)
  local parts = {}
  for _, k in ipairs(schema.OPT_ORDER) do
    local v = e.opts and e.opts[k]
    if v ~= nil then
      parts[#parts + 1] = ("%s = %s"):format(k, type(v) == "string" and quote(v) or tostring(v))
    end
  end
  local raw = vim.tbl_keys(e.opts_raw or {})
  table.sort(raw)
  for _, k in ipairs(raw) do
    parts[#parts + 1] = ("%s = %s"):format(k, e.opts_raw[k])
  end
  if #parts == 0 then
    return nil
  end
  return "{ " .. table.concat(parts, ", ") .. " }"
end

--- @param e table a map entry
--- @return string
function M.map_call(e)
  local modes
  if #e.modes == 1 then
    modes = quote(e.modes[1])
  else
    modes = "{ " .. table.concat(vim.tbl_map(quote, e.modes), ", ") .. " }"
  end
  local args = { modes, quote(e.lhs), e.rhs ~= nil and quote(e.rhs) or e.lua }
  local opts = opts_text(e)
  if opts then
    args[#args + 1] = opts
  end
  local call = ("%s(%s)"):format(e.call or schema.DEFAULT_CALL, table.concat(args, ", "))
  if e.trailing and e.trailing ~= "" then
    call = call .. " " .. e.trailing
  end
  if e.comment and e.comment ~= "" then
    call = e.comment .. "\n" .. call
  end
  return call
end

--- A map with no comment that fits on one line sits right under the previous
--- such map; everything else is set off by a blank line.
local function tight(e)
  return e.kind == "map" and not (e.comment and e.comment ~= "") and not M.map_call(e):find("\n", 1, true)
end

--- Everything after the header: preamble, then entries with a box header
--- whenever the category changes.
--- @param tpl table valid, normalized
--- @return string
function M.body(tpl)
  local cats = {}
  for _, c in ipairs(tpl.categories) do
    cats[c.id] = c
  end
  local items = {}
  for _, chunk in ipairs(tpl.preamble) do
    items[#items + 1] = { text = chunk }
  end
  local current
  for _, e in ipairs(tpl.entries) do
    if e.category ~= current then
      current = e.category
      items[#items + 1] = { text = M.box(cats[current].title, cats[current].subtitle) }
    end
    if e.kind == "raw" then
      items[#items + 1] = { text = e.text }
    else
      items[#items + 1] = { text = M.map_call(e), tight = tight(e) }
    end
  end
  local out = {}
  for i, it in ipairs(items) do
    if i > 1 then
      out[#out + 1] = (it.tight and items[i - 1].tight) and "\n" or "\n\n"
    end
    out[#out + 1] = it.text
  end
  return table.concat(out)
end

--- @param tpl table valid, normalized
--- @param opts { template_name: string|nil, target: string|nil }|nil
--- @return string
function M.render(tpl, opts)
  opts = opts or {}
  local target = opts.target or tpl.target
  local head = table.concat(M.header_lines(opts.template_name or "lua/mappings.template.json", target), "\n")
  local body = M.body(tpl)
  return head .. "\n\n" .. body .. (body ~= "" and "\n" or "")
end

--- True when the text carries the AUTOGENERATED header.
--- @param text string
--- @return boolean
function M.has_header(text)
  return vim.startswith(text, M.MARK)
end

--- The text without its AUTOGENERATED header block and the blank line after it.
--- @param text string
--- @return string
function M.strip_header(text)
  if not M.has_header(text) then
    return text
  end
  local lines = vim.split(text, "\n", { plain = true })
  local i = 1
  while lines[i] and vim.startswith(lines[i], "--") do
    i = i + 1
  end
  if lines[i] == "" then
    i = i + 1
  end
  return table.concat(lines, "\n", i)
end

--- @param path string
--- @return string|nil text
function M.read(path)
  local p = Path:new(path)
  if not p:exists() then
    return nil
  end
  return p:read()
end

--- Write `text` to `path` through a temp file in the same directory, so a
--- crash leaves either the old file or the new one.
--- @param path string
--- @param text string
--- @return boolean|nil ok, string|nil err
function M.atomic_write(path, text)
  Path:new(path):parent():mkdir { parents = true, exists_ok = true }
  local tmp = ("%s.%d.tmp"):format(path, vim.uv.hrtime() % 1000000000)
  local fh, err = io.open(tmp, "wb")
  if not fh then
    return nil, ("cannot write %s: %s"):format(tmp, tostring(err))
  end
  fh:write(text)
  fh:close()
  local st = vim.uv.fs_stat(path)
  if st then
    vim.uv.fs_chmod(tmp, st.mode % 4096)
  end
  local ok, rerr = vim.uv.fs_rename(tmp, path)
  if not ok then
    vim.uv.fs_unlink(tmp)
    return nil, ("cannot replace %s: %s"):format(path, tostring(rerr))
  end
  return true
end

--- True when the file on disk is exactly what the template renders to.
--- @param tpl table
--- @param target string
--- @param opts table|nil render options
--- @return boolean in_sync, string|nil reason
function M.check(tpl, target, opts)
  local errs = schema.validate(tpl)
  if #errs > 0 then
    return false, "template is invalid: " .. errs[1]
  end
  local disk = M.read(target)
  if not disk then
    return false, target .. " does not exist"
  end
  if disk ~= M.render(tpl, vim.tbl_extend("force", { target = target }, opts or {})) then
    return false, target .. " differs from what the template generates"
  end
  return true
end

--- Validate, back up the old file, write the new one.
--- @param tpl table normalized template
--- @param target string
--- @param opts { backups: boolean|nil, now: integer|nil, template_name: string|nil }|nil
--- @return table|nil result { changed, backup }, string|nil err
function M.write(tpl, target, opts)
  opts = opts or {}
  local errs = schema.validate(tpl)
  if #errs > 0 then
    return nil, "template is invalid, nothing was written:\n  " .. table.concat(errs, "\n  ")
  end
  local text = M.render(tpl, { target = target, template_name = opts.template_name })
  if M.read(target) == text then
    return { changed = false }
  end
  local bak, err
  if opts.backups ~= false then
    bak, err = backup.create(target, opts.now)
    if err then
      return nil, err
    end
  end
  local ok, werr = M.atomic_write(target, text)
  if not ok then
    return nil, werr
  end
  return { changed = true, backup = bak }
end

return M
